function eraseOverlapIntervals(intervals) {
  const sorted = intervals.map((pair) => [pair[0], pair[1]]).sort((a, b) => a[0] - b[0]);
  let removals = 0;
  let currentEnd = Infinity;
  for (let i = 0; i < sorted.length; i++) {
    if (i === 0) { currentEnd = sorted[i][1]; continue; }
    if (sorted[i][0] < currentEnd) {
      removals++;
      currentEnd = Math.min(currentEnd, sorted[i][1]);
    } else {
      currentEnd = sorted[i][1];
    }
  }
  return removals;
}

