function findMinArrowShots(points) {
  let alive = points.map((pair) => [pair[0], pair[1]]).sort((a, b) => (a[1] < b[1] ? -1 : a[1] > b[1] ? 1 : 0));
  let arrows = 0;
  while (alive.length > 0) {
    const arrow = alive[0][1];
    arrows++;
    alive = alive.filter((pair) => pair[0] > arrow);
  }
  return arrows;
}

function findMinArrowShots(points) {
  const sorted = points.map((pair) => [pair[0], pair[1]]).sort((a, b) => (a[1] < b[1] ? -1 : a[1] > b[1] ? 1 : 0));
  let arrows = 1;
  let arrow = sorted[0][1];
  for (let i = 1; i < sorted.length; i++) {
    if (sorted[i][0] > arrow) {
      arrows++;
      arrow = sorted[i][1];
    }
  }
  return arrows;
}

