function findLongestChain(pairs) {
  const sorted = pairs.map((pair) => [pair[0], pair[1]]).sort((a, b) => a[0] - b[0]);
  const best = new Array(sorted.length).fill(1);
  let answer = 1;
  for (let i = 0; i < sorted.length; i++) {
    for (let j = 0; j < i; j++) {
      if (sorted[j][1] < sorted[i][0] && best[j] + 1 > best[i]) best[i] = best[j] + 1;
    }
    if (best[i] > answer) answer = best[i];
  }
  return answer;
}

code.python:
def find_longest_chain(pairs):
    ordered = sorted(pairs, key=lambda pair: pair[0])
    best = [1] * len(ordered)
    answer = 1
    for i in range(len(ordered)):
        for j in range(i):
            if ordered[j][1] < ordered[i][0] and best[j] + 1 > best[i]:
                best[i] = best[j] + 1
        answer = max(answer, best[i])
    return answer

